/** @jest-environment jsdom */

"use strict";

const fs = require("node:fs");
const path = require("node:path");
const app = require("../app/app.js");

const html = fs.readFileSync(path.resolve(__dirname, "../app/index.html"), "utf8");
const bodyMarkup = html.match(/<body[^>]*>([\s\S]*)<\/body>/i)[1]
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, "");

const coursesFixture = [
  {
    id: "calc-201", code: "MAT-201", name: "Cálculo diferencial", teacher: "Dra. Elena Torres",
    schedule: "Lun · Mié · 10:00 a. m.", room: "B-204", credits: 4, average: 16.8,
    grades: { t1: 17, t2: 16, t3: 18, final: 17.2 },
  },
  {
    id: "met-220", code: "INV-220", name: "Metodología de investigación", teacher: "Dra. Lucía Herrera",
    schedule: "Mar · Vie · 2:00 p. m.", room: "C-301", credits: 3, average: 15.6,
    grades: { t1: 15, t2: 16, t3: null, final: 15.5 },
  },
];

beforeEach(() => {
  document.body.innerHTML = bodyMarkup;
  app.setCourses(coursesFixture);
  app.setMessages([]);
});

describe("lógica del cliente del aula virtual", () => {
  test("escapa caracteres HTML especiales", () => {
    expect(app.escapeHtml(`<script a="b">'&`)).toBe("&lt;script a=&quot;b&quot;&gt;&#39;&amp;");
  });

  test("renderiza una fila de curso con promedio y progreso", () => {
    const htmlRow = app.renderCourseRow(coursesFixture[0], 0);
    expect(htmlRow).toContain("Cálculo diferencial");
    expect(htmlRow).toContain("Dra. Elena Torres");
    expect(htmlRow).toContain("16.8");
    expect(htmlRow).toContain("width-80");
  });

  test("escapa el contenido no confiable de un curso", () => {
    const htmlRow = app.renderCourseRow({ ...coursesFixture[0], name: "<img src=x onerror=alert(1)>" }, 0);
    expect(htmlRow).toContain("&lt;img src=x onerror=alert(1)&gt;");
    expect(htmlRow).not.toContain("<img src=x");
  });

  test("renderiza cursos, notas y opciones de selección", () => {
    app.renderCourses();
    expect(document.querySelectorAll("#all-courses .course-tile")).toHaveLength(2);
    expect(document.querySelector("#grades-body").textContent).toContain("15.5");
    expect(document.querySelector("#grades-body").textContent).toContain("—");
    expect(document.querySelectorAll("#message-course option")).toHaveLength(3);
  });

  test("muestra el estado vacío de la bandeja", () => {
    app.renderMessages();
    expect(document.querySelector("#messages-list .empty-messages").textContent)
      .toContain("Todavía no has enviado mensajes");
  });

  test("renderiza mensajes del más reciente al más antiguo", () => {
    app.setMessages([
      { teacherInitials: "ET", teacher: "Dra. Elena Torres", subject: "Primero", courseName: "Cálculo", body: "Mensaje uno", createdAt: "2026-01-01T10:00:00Z" },
      { teacherInitials: "LM", teacher: "Lic. Laura Mora", subject: "Segundo", courseName: "Bases de datos", body: "Mensaje dos", createdAt: "2026-01-02T10:00:00Z" },
    ]);
    app.renderMessages();
    const entries = [...document.querySelectorAll("#messages-list .message-entry")];
    expect(entries).toHaveLength(2);
    expect(entries[0].textContent).toContain("Segundo");
    expect(entries[1].textContent).toContain("Primero");
  });

  test("escapa contenido de mensajes antes de insertarlo en la bandeja", () => {
    app.setMessages([{
      teacherInitials: "ET", teacher: "Dra. Elena Torres", subject: "<b>Asunto</b>", courseName: "Cálculo",
      body: "<img src=x onerror=alert(1)>", createdAt: "2026-01-02T10:00:00Z",
    }]);
    app.renderMessages();
    expect(document.querySelector("#messages-list b")).toBeNull();
    expect(document.querySelector("#messages-list img")).toBeNull();
    expect(document.querySelector("#messages-list").innerHTML).toContain("&lt;img");
  });

  test("muestra una sección válida y actualiza navegación", () => {
    app.showView("cursos");
    expect(document.querySelector("#view-cursos").classList.contains("hidden")).toBe(false);
    expect(document.querySelector("#view-inicio").classList.contains("hidden")).toBe(true);
    expect(document.querySelector("#breadcrumb-current").textContent).toBe("Mis cursos");
    expect(document.querySelector('[data-view="cursos"]').classList.contains("active")).toBe(true);
  });

  test("ignora una sección inexistente sin cambiar la vista", () => {
    app.showView("inicio");
    const breadcrumb = document.querySelector("#breadcrumb-current").textContent;
    const hash = location.hash;
    app.showView("biblioteca");
    expect(document.querySelector("#view-inicio").classList.contains("hidden")).toBe(false);
    expect(document.querySelector("#breadcrumb-current").textContent).toBe(breadcrumb);
    expect(location.hash).toBe(hash);
  });

  test("rechaza curso, asunto o mensaje ausentes y valores con solo espacios", () => {
    expect(app.validateMessagePayload({ subject: "Asunto válido", body: "Mensaje válido" })).not.toBe("");
    expect(app.validateMessagePayload({ courseId: "calc-201", subject: "   ", body: "Mensaje válido" })).not.toBe("");
    expect(app.validateMessagePayload({ courseId: "calc-201", subject: "Asunto válido", body: "    " })).not.toBe("");
  });

  test("valida los límites inferior y superior del asunto", () => {
    const valid = { courseId: "calc-201", subject: "Asunto", body: "Mensaje válido" };
    expect(app.validateMessagePayload({ ...valid, subject: "ab" })).not.toBe("");
    expect(app.validateMessagePayload({ ...valid, subject: "abc" })).toBe("");
    expect(app.validateMessagePayload({ ...valid, subject: "a".repeat(100) })).toBe("");
    expect(app.validateMessagePayload({ ...valid, subject: "a".repeat(101) })).not.toBe("");
  });

  test("valida los límites inferior y superior del mensaje", () => {
    const valid = { courseId: "calc-201", subject: "Consulta", body: "Mensaje" };
    expect(app.validateMessagePayload({ ...valid, body: "abcd" })).not.toBe("");
    expect(app.validateMessagePayload({ ...valid, body: "abcde" })).toBe("");
    expect(app.validateMessagePayload({ ...valid, body: "a".repeat(1000) })).toBe("");
    expect(app.validateMessagePayload({ ...valid, body: "a".repeat(1001) })).not.toBe("");
  });

  test("permite continuar con un mensaje válido", () => {
    expect(app.validateMessagePayload({
      courseId: "calc-201", subject: "Consulta de práctica", body: "¿Puede explicar el ejercicio tres?",
    })).toBe("");
  });
});

"use strict";

const request = require("supertest");
const { createServer } = require("../backend/server.js");

describe("integración HTTP de Aula Nova", () => {
  let server;
  let baselineMessages;

  beforeEach(async () => {
    server = createServer();
    const response = await request(server).get("/api/messages");
    baselineMessages = response.body.messages.length;
  });

  afterEach(async () => {
    if (server.listening) {
      await new Promise((resolve, reject) => {
        server.close(error => error ? reject(error) : resolve());
      });
    }
  });

  test("sirve la página principal con cabeceras de seguridad", async () => {
    const response = await request(server).get("/");
    expect(response.status).toBe(200);
    expect(response.headers["content-type"]).toMatch(/text\/html/);
    expect(response.headers["x-frame-options"]).toBe("DENY");
    expect(response.headers["content-security-policy"]).toContain("default-src 'self'");
    expect(response.text).toContain("Aula Nova");
  });

  test("sirve los recursos CSS y JavaScript", async () => {
    const [css, js] = await Promise.all([
      request(server).get("/styles.css"),
      request(server).get("/app.js"),
    ]);
    expect(css.status).toBe(200);
    expect(css.headers["content-type"]).toMatch(/text\/css/);
    expect(js.status).toBe(200);
    expect(js.headers["content-type"]).toMatch(/javascript/);
  });

  test("devuelve el perfil con su estructura académica", async () => {
    const response = await request(server).get("/api/student");
    expect(response.status).toBe(200);
    expect(response.body.student).toMatchObject({
      firstName: expect.any(String),
      lastName: expect.any(String),
      code: "202310458",
      email: expect.any(String),
      program: expect.any(String),
      faculty: expect.any(String),
      cycle: expect.any(String),
    });
  });

  test("devuelve cuatro cursos con notas y T3 pendiente", async () => {
    const response = await request(server).get("/api/courses");
    expect(response.status).toBe(200);
    expect(response.body.courses).toHaveLength(4);
    expect(Object.keys(response.body.courses[0].grades)).toEqual(["t1", "t2", "t3", "final"]);
    expect(response.body.courses.find(course => course.id === "met-220").grades.t3).toBeNull();
  });

  test("devuelve la bandeja como un arreglo de mensajes", async () => {
    const response = await request(server).get("/api/messages");
    expect(response.status).toBe(200);
    expect(Array.isArray(response.body.messages)).toBe(true);
    expect(response.body.messages).toHaveLength(baselineMessages);
  });

  test("registra un mensaje válido y asigna el docente del curso", async () => {
    const response = await request(server).post("/api/messages").send({
      courseId: "calc-201",
      subject: "  Consulta de práctica  ",
      body: "  ¿Puede explicar el ejercicio tres?  ",
    });
    expect(response.status).toBe(201);
    expect(response.body.message).toMatchObject({
      courseId: "calc-201",
      teacher: "Dra. Elena Torres",
      subject: "Consulta de práctica",
      body: "¿Puede explicar el ejercicio tres?",
    });
    expect(Date.parse(response.body.message.createdAt)).not.toBeNaN();
  });

  test("mantiene temporalmente los mensajes durante la vida del servidor", async () => {
    const first = await request(server).post("/api/messages").send({
      courseId: "calc-201", subject: "Primera consulta", body: "Mensaje de prueba uno.",
    });
    const second = await request(server).post("/api/messages").send({
      courseId: "prog-105", subject: "Segunda consulta", body: "Mensaje de prueba dos.",
    });
    const inbox = await request(server).get("/api/messages");
    expect(first.status).toBe(201);
    expect(second.status).toBe(201);
    expect(inbox.body.messages).toHaveLength(baselineMessages + 2);
    expect(inbox.body.messages.map(message => message.subject)).toEqual(expect.arrayContaining([
      "Primera consulta", "Segunda consulta",
    ]));
  });

  test("rechaza un curso inexistente sin guardar el mensaje", async () => {
    const response = await request(server).post("/api/messages").send({
      courseId: "curso-inexistente", subject: "Consulta válida", body: "Texto de consulta válido.",
    });
    const inbox = await request(server).get("/api/messages");
    expect(response.status).toBe(400);
    expect(response.body.error).toBeTruthy();
    expect(inbox.body.messages).toHaveLength(baselineMessages);
  });

  test("rechaza campos ausentes y longitudes fuera de límites", async () => {
    const invalidPayloads = [
      { subject: "Consulta válida", body: "Texto de consulta válido." },
      { courseId: "calc-201", subject: "ab", body: "Texto de consulta válido." },
      { courseId: "calc-201", subject: "a".repeat(101), body: "Texto de consulta válido." },
      { courseId: "calc-201", subject: "Consulta válida", body: "abcd" },
      { courseId: "calc-201", subject: "Consulta válida", body: "x".repeat(1001) },
    ];
    for (const payload of invalidPayloads) {
      const response = await request(server).post("/api/messages").send(payload);
      expect(response.status).toBe(400);
      expect(response.body.error).toBeTruthy();
    }
    const inbox = await request(server).get("/api/messages");
    expect(inbox.body.messages).toHaveLength(baselineMessages);
  });

  test("rechaza JSON mal formado", async () => {
    const response = await request(server)
      .post("/api/messages")
      .set("Content-Type", "application/json")
      .send("{");
    expect(response.status).toBe(400);
    expect(response.body.error).toMatch(/JSON válido/i);
  });

  test("rechaza cuerpos que superan 16 KiB", async () => {
    const response = await request(server).post("/api/messages").send({ body: "x".repeat(17 * 1024) });
    expect(response.status).toBe(413);
    expect(response.body.error).toMatch(/tamaño permitido/i);
  });

  test("devuelve 404 para rutas desconocidas y 403 fuera de app", async () => {
    const [webRoute, apiRoute, traversal] = await Promise.all([
      request(server).get("/ruta-inexistente"),
      request(server).get("/api/ruta-inexistente"),
      request(server).get("/..%2Fbackend%2Fserver.js"),
    ]);
    expect(webRoute.status).toBe(404);
    expect(apiRoute.status).toBe(404);
    expect(traversal.status).toBe(403);
  });
});

const test = require("node:test");
const assert = require("node:assert/strict");
const { createServer } = require("./server");

test("API y aplicación web del aula virtual", async (suite) => {
  const server = createServer();
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  const baseUrl = `http://127.0.0.1:${server.address().port}`;

  suite.after(() => new Promise((resolve, reject) => server.close((error) => error ? reject(error) : resolve())));

  await suite.test("entrega la página de inicio y cabeceras de seguridad", async () => {
    const response = await fetch(baseUrl);
    assert.equal(response.status, 200);
    assert.match(response.headers.get("content-type"), /text\/html/);
    assert.equal(response.headers.get("x-frame-options"), "DENY");
    assert.match(await response.text(), /Aula Nova/);
  });

  await suite.test("expone el perfil y los cuatro cursos con calificaciones", async () => {
    const [studentResponse, coursesResponse] = await Promise.all([
      fetch(`${baseUrl}/api/student`), fetch(`${baseUrl}/api/courses`),
    ]);
    const profile = await studentResponse.json();
    const data = await coursesResponse.json();
    assert.equal(profile.student.code, "202310458");
    assert.equal(data.courses.length, 4);
    assert.deepEqual(Object.keys(data.courses[0].grades), ["t1", "t2", "t3", "final"]);
  });

  await suite.test("envía mensajes y los devuelve en la bandeja", async () => {
    const response = await fetch(`${baseUrl}/api/messages`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ courseId: "calc-201", subject: "Consulta de práctica", body: "¿Podría explicar el ejercicio número tres?" }),
    });
    assert.equal(response.status, 201);
    const { message } = await response.json();
    assert.equal(message.teacher, "Dra. Elena Torres");
    assert.equal((await (await fetch(`${baseUrl}/api/messages`)).json()).messages.length, 1);
  });

  await suite.test("rechaza mensajes incompletos y cursos desconocidos", async () => {
    const response = await fetch(`${baseUrl}/api/messages`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ courseId: "desconocido", subject: "Ok", body: "No" }),
    });
    assert.equal(response.status, 400);
    assert.equal((await response.json()).error.length > 0, true);
  });

  await suite.test("rechaza JSON inválido y solicitudes demasiado grandes", async () => {
    const invalid = await fetch(`${baseUrl}/api/messages`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: "{",
    });
    assert.equal(invalid.status, 400);

    const oversized = await fetch(`${baseUrl}/api/messages`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ body: "x".repeat(17 * 1024) }),
    });
    assert.equal(oversized.status, 413);
  });

  await suite.test("no expone archivos fuera de la aplicación", async () => {
    const response = await fetch(`${baseUrl}/..%2Fbackend%2Fserver.js`);
    assert.equal(response.status, 403);
  });
});
